/**
 * An approved WhatsApp template and the values of its variables.
 */
export type TemplateMessage = {
    /**
     * Approved template ID from `GET /templates`.
     */
    id: string;
    /**
     * Variable values, in the WhatsApp Cloud API format.
     */
    components?: Array<{
        type: 'header' | 'body' | 'button';
        sub_type?: 'url' | 'quick_reply';
        /**
         * Button position, from `"0"`.
         */
        index?: string;
        parameters: Array<{
            type: 'text';
            text: string;
            /**
             * For `NAMED` templates.
             */
            parameter_name?: string;
        } | {
            type: 'payload';
            payload: string;
        } | {
            type: 'image';
            /**
             * Media file.
             */
            image: {
                /**
                 * Public HTTPS URL of the file.
                 */
                link: string;
            };
        } | {
            type: 'video';
            /**
             * Media file.
             */
            video: {
                /**
                 * Public HTTPS URL of the file.
                 */
                link: string;
            };
        } | {
            type: 'document';
            document: {
                /**
                 * Public HTTPS URL of the file.
                 */
                link: string;
                filename?: string;
            };
        } | {
            type: 'currency';
            currency: {
                amount_1000: number;
                code: string;
                fallback_value: string;
            };
        } | {
            type: 'date_time';
            date_time: {
                fallback_value: string;
            };
        }>;
    }>;
};

/**
 * A file Ricky downloads and sends. WhatsApp and Instagram only.
 */
export type MediaMessage = {
    /**
     * Public HTTPS URL of the file. Ricky downloads it once, without following redirects.
     */
    url: string;
    /**
     * How the channel shows the file. The file type must match it.
     */
    kind: 'image' | 'video' | 'audio' | 'document';
    /**
     * Text under an image, video or document. WhatsApp only.
     */
    caption?: string;
    /**
     * Name the recipient sees for a document. Defaults to the last segment of `url`.
     */
    filename?: string;
};

/**
 * Text and media work inside the channel reply window; a template (WhatsApp only) works any time.
 */
export type SendMessage = {
    type: 'text';
    /**
     * Message text.
     */
    text: string;
} | {
    type: 'template';
    template: TemplateMessage;
} | {
    type: 'media';
    media: MediaMessage;
};

